/// Every field that decides who may do what is guarded by a storage type,
/// because a member running a modified node skips every check in the methods
/// below and writes plain fields directly:
///
/// | field | who may write it, on every node |
/// |---|---|
/// | `is_private`, `owner`, `context_name` | nobody after `init` (`Frozen`) |
/// | `roles` | admins (`AccessControl`'s writer set) |
/// | `joined` | each account its own slot (`UserStorage`) |
/// | `documents` | anyone adds; nobody edits; admins remove (`ModeratedOnce`) |
/// | `document_signatures` | each signer their own; nobody edits or removes (`WriteOnce`) |
/// | `consents` | each account its own slot (`UserStorage`) |
///
/// The private-context fields (`signatures`, `joined_contexts`,
/// `identity_mappings`) are plain: a private context holds its owner's
/// account alone.
public struct MeroSignState: Codable, Sendable, Equatable {
    public var isPrivate: Bool
    public var owner: ContractBytes
    public var contextName: String
    public var signatures: [String: SignatureRecord]
    public var joinedContexts: [String: ContextMetadata]
    public var identityMappings: [String: IdentityMapping]
    /// Admin, signer and viewer grants, and removals.
    public var roles: [String: Bool]
    /// Accounts that registered themselves through an open invitation: `Sign`
    /// unless an admin set another level or removed them.
    public var joined: [String: UInt64]
    /// Moderated by the admins, kept equal to `roles.admins()`.
    public var documents: [String: StoredDocument]
    /// `"{document_id}/{signer hex}/{nonce}"`: a document's signatures are one
    /// prefix, and the nonce leaves no key for anyone to occupy first.
    public var documentSignatures: [String: SignedVersion]
    public var consents: [String: Consents]

    public init(isPrivate: Bool, owner: ContractBytes, contextName: String, signatures: [String: SignatureRecord], joinedContexts: [String: ContextMetadata], identityMappings: [String: IdentityMapping], roles: [String: Bool], joined: [String: UInt64], documents: [String: StoredDocument], documentSignatures: [String: SignedVersion], consents: [String: Consents]) {
        self.isPrivate = isPrivate
        self.owner = owner
        self.contextName = contextName
        self.signatures = signatures
        self.joinedContexts = joinedContexts
        self.identityMappings = identityMappings
        self.roles = roles
        self.joined = joined
        self.documents = documents
        self.documentSignatures = documentSignatures
        self.consents = consents
    }

    enum CodingKeys: String, CodingKey {
        case isPrivate = "is_private"
        case owner
        case contextName = "context_name"
        case signatures
        case joinedContexts = "joined_contexts"
        case identityMappings = "identity_mappings"
        case roles
        case joined
        case documents
        case documentSignatures = "document_signatures"
        case consents
    }
}

