        case name
        case blobId = "blob_id"
        case size
        case createdAt = "created_at"
    }
}

/// One signature: the signer (the entry's owner stamp) took the version at
/// `base_hash`, put their mark on it, and produced the version at `new_hash`,
/// stored as `pdf_blob_id`. Written once, so a signature can be neither
/// withdrawn nor edited, and the version it signed stays on record.
public struct SignedVersion: Codable, Sendable, Equatable {
    public var baseHash: String
    public var newHash: String
    public var pdfBlobId: ContractBytes
    public var size: UInt64
    public var signedAt: UInt64

    public init(baseHash: String, newHash: String, pdfBlobId: ContractBytes, size: UInt64, signedAt: UInt64) {
        self.baseHash = baseHash
        self.newHash = newHash
        self.pdfBlobId = pdfBlobId
        self.size = size
        self.signedAt = signedAt
    }

    enum CodingKeys: String, CodingKey {
        case baseHash = "base_hash"
        case newHash = "new_hash"
        case pdfBlobId = "pdf_blob_id"
        case size
        case signedAt = "signed_at"
    }
}

/// A document as uploaded. Written once: nobody, the uploader included, can
/// change it afterwards, and only an admin (a moderator of `documents`) can
/// remove it. The uploader is the entry's owner stamp.
///
/// What signing changes is recorded beside it, one write-once
/// [`SignedVersion`] per signature, never by rewriting this.
public struct StoredDocument: Codable, Sendable, Equatable {
    public var name: String
    public var hash: String
    public var pdfBlobId: ContractBytes
    public var size: UInt64
    public var uploadedAt: UInt64
    /// Who must sign it: every participant holding `Sign` or `Admin` when it
    /// was uploaded. Fixed with the document, so completion is a fact about
    /// the past — nobody who joins later reopens it.
    public var requiredSigners: [ContractBytes]
    public var embeddings: [Float]?
    public var extractedText: String?
    public var chunks: [DocumentChunk]?

    public init(name: String, hash: String, pdfBlobId: ContractBytes, size: UInt64, uploadedAt: UInt64, requiredSigners: [ContractBytes], embeddings: [Float]? = nil, extractedText: String? = nil, chunks: [DocumentChunk]? = nil) {
        self.name = name
        self.hash = hash
        self.pdfBlobId = pdfBlobId
        self.size = size
        self.uploadedAt = uploadedAt
        self.requiredSigners = requiredSigners
        self.embeddings = embeddings
        self.extractedText = extractedText
        self.chunks = chunks
    }

    enum CodingKeys: String, CodingKey {
        case name
        case hash
        case pdfBlobId = "pdf_blob_id"
        case size
        case uploadedAt = "uploaded_at"
        case requiredSigners = "required_signers"
        case embeddings
        case extractedText = "extracted_text"
        case chunks
    }
}

// MARK: - Wire helpers

/// Fixed-size bytes. An id with its own spelling (`UserId`, `BlobId`) is
/// ``text`` — base58 or hex, exactly as the contract writes it — and a plain
/// `[u8; N]` is ``raw``, an array of numbers. Decoding takes whichever arrives;
/// encoding writes the form this value holds.
public enum ContractBytes: Codable, Sendable, Equatable, Hashable, ExpressibleByStringLiteral {
    case text(String)
    case raw([UInt8])

    public init(stringLiteral value: String) { self = .text(value) }

    /// The text form, if that is what this holds.
    public var text: String? { if case .text(let value) = self { value } else { nil } }
    /// The array form, if that is what this holds.
    public var raw: [UInt8]? { if case .raw(let value) = self { value } else { nil } }

    public init(from decoder: any Decoder) throws {
        let container = try decoder.singleValueContainer()
        if let value = try? container.decode(String.self) {
            self = .text(value)
        } else {
            self = .raw(try container.decode([UInt8].self))
        }
    }

    public func encode(to encoder: any Encoder) throws {
        var container = encoder.singleValueContainer()
        switch self {
        case .text(let value): try container.encode(value)
        case .raw(let value): try container.encode(value)
        }
    }
}
